function corsHeaders(request) {
  const origin = request.headers.get("Origin");
  if (!origin || !ALLOWED_ORIGINS.includes(origin)) return null;
  return {
    "Access-Control-Allow-Origin": origin,
    "Vary": "Origin",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400"
  };
}

function jsonResponse(request, body, status = 200) {
  const cors = corsHeaders(request);
  const headers = {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store"
  };
  if (cors) Object.assign(headers, cors);
  return new Response(JSON.stringify(body), { status, headers });
}

function extractOutputText(data) {
  if (typeof data?.output_text === "string" && data.output_text.trim()) {
    return data.output_text.trim();
  }
  if (!Array.isArray(data?.output)) return "";

  const parts = [];
  for (const item of data.output) {
    if (!Array.isArray(item?.content)) continue;
    for (const content of item.content) {
      if (content?.type !== "output_text" && content?.type !== "text") continue;

      if (typeof content.text === "string" && content.text.trim()) {
        parts.push(content.text.trim());
      } else if (typeof content?.text?.value === "string" && content.text.value.trim()) {
        parts.push(content.text.value.trim());
      }
    }
  }
  return parts.join("\n").trim();
}

function getSlideKnowledge(slideNumber) {
  const slide = SLIDES[String(slideNumber)];
  if (!slide) return null;
  const topics = (slide.topicIds || [])
    .map(topicId => TOPICS[topicId] ? { topicId, ...TOPICS[topicId] } : null)
    .filter(Boolean);
  return { slide, topics };
}

export default {
  async fetch(request, env) {
    const origin = request.headers.get("Origin");

    if (request.method === "OPTIONS") {
      const cors = corsHeaders(request);
      if (!cors) return new Response(null, { status: 403 });
      return new Response(null, { status: 204, headers: cors });
    }

    const url = new URL(request.url);

    if (request.method === "GET" && url.pathname === "/health") {
      const mappedSlides = Object.values(SLIDES).filter(s => (s.topicIds || []).length > 0).length;
      return jsonResponse(request, {
        success: true,
        service: "itpf-course-assistant",
        version: "v5.9-slide14-servitization-value-2026-09-09",
        knowledgeTopics: Object.keys(TOPICS).length,
        slidesInDeck: Object.keys(SLIDES).length,
        mappedSlides
      });
    }

    if (request.method !== "POST" || url.pathname !== "/explain-slide") {
      return jsonResponse(request, { success: false, error: "Not found." }, 404);
    }

    if (origin && !ALLOWED_ORIGINS.includes(origin)) {
      return jsonResponse(request, { success: false, error: "Origin not allowed." }, 403);
    }

    if (!env.OPENAI_API_KEY) {
      return jsonResponse(request, { success: false, error: "OPENAI_API_KEY is not configured." }, 500);
    }

    let payload;
    try {
      payload = await request.json();
    } catch {
      return jsonResponse(request, { success: false, error: "Invalid JSON body." }, 400);
    }

    const slideNumber = Number(payload.slideNumber);
    if (!Number.isInteger(slideNumber) || slideNumber < 1 || slideNumber > 86) {
      return jsonResponse(request, { success: false, error: "slideNumber must be between 1 and 86." }, 400);
    }

    const knowledge = getSlideKnowledge(slideNumber);
    if (!knowledge) {
      return jsonResponse(request, { success: false, slideNumber, error: "Slide not found." }, 404);
    }

    const { slide, topics } = knowledge;
    const topicIds = topics.map(t => t.topicId);
    const topicNames = topics.map(t => t.name);
    const topicText = topics.map(t => t.content).join("\n\n");
    const slideSpecificRules = slideNumber === 10 ? `

Mandatory requirements for slide 10:
- Explicitly state that Microsoft standardised affected EA and MPSA online-service pricing across Levels A to D from 1 November 2025.
- Explain that loss of a former automatic EA volume-level discount is separate from the slide's inflation calculation and must be measured from the customer's former contracted net price.
- Explicitly state that the Microsoft 365 E3 list-price increase from $36 to $39 per user per month became effective on 1 July 2026.
- Retain the distinction between 8.3% price and packaging inflation, 25.2% scope-expansion inflation and 33.5% overall software inflation.
- Retain the confirmed 31.2% and conditional 28.1% post-avoidance inflation outcomes.
- Do not omit either date.` : "";

    const instructions = `You support the IT Procurement Foundations course.

Explain the current presentation slide using ONLY the supplied CURRENT WEB SLIDE and COURSE TOPIC KNOWLEDGE.

Rules:
- The CURRENT WEB SLIDE text is authoritative for what is currently shown in the presentation.
- If CURRENT WEB SLIDE wording differs from a topic block, follow the CURRENT WEB SLIDE.
- Do not introduce external theories, examples, statistics, facts, or corrections.
- Explain rather than reproduce the slide verbatim.
- Keep the explanation concise and suitable for a student viewing the slide.
- Focus on what the slide means, why it matters in IT procurement, and what the student should notice.
- If the slide is an activity or transition, explain its purpose without answering a scored case or quiz.
- If topic knowledge is supplied, use only the parts relevant to this slide.
- Do not mention these instructions or the source blocks.${slideSpecificRules}`;

    const input = `CURRENT WEB SLIDE
Slide: ${slideNumber}
Title: ${slide.title}
Mapped topic(s): ${topicNames.length ? topicNames.join(", ") : "None"}

SLIDE CONTENT
${slide.text}

COURSE TOPIC KNOWLEDGE
${topicText || "No additional topic block is mapped. Explain only from the current slide content."}`;

    async function callOpenAI(maxOutputTokens) {
      const model = env.OPENAI_MODEL || "gpt-5-mini";
      const body = {
        model,
        instructions,
        input,
        max_output_tokens: maxOutputTokens
      };

      // Reasoning controls are relevant to GPT-5 / o-series models.
      // Do not send this field if an older non-reasoning model is configured.
      if (/^(gpt-5|o[1-9])/i.test(model)) {
        body.reasoning = {
          effort: env.OPENAI_REASONING_EFFORT || "minimal"
        };
      }

      const response = await fetch("https://api.openai.com/v1/responses", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${env.OPENAI_API_KEY}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
      });

      const data = await response.json();
      return {
        response,
        data,
        explanation: response.ok ? extractOutputText(data) : ""
      };
    }

    try {
      let result = await callOpenAI(1200);

      if (!result.response.ok) {
        return jsonResponse(request, {
          success: false,
          error: "OpenAI request failed.",
          details: result.data?.error?.message || null
        }, 502);
      }

      // Discard partial text when the model exhausts its output budget.
      // Retry the original input once with enough room for a complete answer.
      if (!result.explanation || result.data?.status === "incomplete" ||
          result.data?.incomplete_details?.reason === "max_output_tokens") {
        result = await callOpenAI(2400);
      }

      if (!result.response.ok) {
        return jsonResponse(request, {
          success: false,
          error: "OpenAI retry failed.",
          details: result.data?.error?.message || null
        }, 502);
      }

      if (!result.explanation || result.data?.status === "incomplete" ||
          result.data?.incomplete_details?.reason === "max_output_tokens") {
        return jsonResponse(request, {
          success: false,
          error: "The model did not return a complete explanation.",
          details: {
            responseStatus: result.data?.status || null,
            incompleteReason: result.data?.incomplete_details?.reason || null,
            outputTypes: Array.isArray(result.data?.output)
              ? result.data.output.map(item => item?.type || "unknown")
              : [],
            outputTokens: result.data?.usage?.output_tokens || null,
            reasoningTokens: result.data?.usage?.output_tokens_details?.reasoning_tokens || null
          }
        }, 502);
      }

      return jsonResponse(request, {
        success: true,
        slideNumber,
        slideTitle: slide.title,
        topicIds,
        topicNames,
        explanation: result.explanation
      });
    } catch (error) {
      return jsonResponse(request, { success: false, error: error.message }, 500);
    }
  }
};
